// Problem: does any pair in a sorted array sum to target?

// Brute force: O(n²)
fun hasPairBrute(a: IntArray, target: Int): Boolean {
    for (i in a.indices)
        for (j in i + 1 until a.size)
            if (a[i] + a[j] == target) return true
    return false
}

// Clue: sorted + pair  ->  Two Pointers: O(n)
fun hasPair(a: IntArray, target: Int): Boolean {
    var l = 0
    var r = a.size - 1
    while (l < r) {
        val sum = a[l] + a[r]
        when {
            sum == target -> return true
            sum < target -> l++
            else -> r--
        }
    }
    return false
}
